      "support_status": "SUFFICIENT",
      "rationale": "The cited span explicitly supplies the evidence condition and reporting consequence."
    }
  },
  "signal_basis": {
    "component_id": "C044.signal_basis",
    "value": "The safe observation window cannot provide enough evidence under the observation duration and precision requirement set beforehand using available overnight volume and the smallest operationally meaningful improvement.",
    "scope": "Assumed evidence insufficiency within the bounded experiment's safety window.",
    "provenance": {
      "refs": [
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies both the evidence-planning criteria and the condition that the safety window cannot supply sufficient evidence."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C044.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed for this reporting decision."
    }
  },
  "rationale": "Given insufficient evidence within the safe observation window, reporting uncertainty is warranted. The claim is limited to how the result should be reported and requires no further inference about the cause of export delays.",
